import{_ as t,a,o as s,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Delete All Compare Items","description":"","frontmatter":{"outline":false,"examples":[{"id":"delete-all-compare-items","title":"Delete All Compare Items","description":"Remove every product from the authenticated customer's comparison list.","request":"POST /api/shop/delete-all-compare-items\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer <accessToken>\\n\\n{}\\n","response":"HTTP/1.1 201 Created\\n\\n{\\n  \\"message\\": \\"All compare items have been removed successfully\\",\\n  \\"deletedCount\\": 2\\n}\\n","commonErrors":[{"error":"403 Forbidden","cause":"No customer Bearer token was sent","solution":"Log the customer in; guests hold no comparison list"},{"error":"deletedCount of 0","cause":"The comparison list was already empty","solution":"This is a success, not a failure — the call is safe to repeat"}]}]},"headers":[],"relativePath":"api/rest-api/shop/compare/delete-all.md","filePath":"api/rest-api/shop/compare/delete-all.md","lastUpdated":1787290888000}`),r={name:"api/rest-api/shop/compare/delete-all.md"};function l(d,e,i,n,c,h){return s(),a("div",null,e[0]||(e[0]=[o('<h1 id="delete-all-compare-items" tabindex="-1">Delete All Compare Items <a class="header-anchor" href="#delete-all-compare-items" aria-label="Permalink to &quot;Delete All Compare Items&quot;">​</a></h1><p>Remove every product from the authenticated customer&#39;s comparison list in a single request.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/delete-all-compare-items</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Customer Bearer token (<code>Bearer &lt;accessToken&gt;</code>)</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><p>No fields are required. Send an empty JSON object:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><h2 id="response-fields-201-created" tabindex="-1">Response Fields (201 Created) <a class="header-anchor" href="#response-fields-201-created" aria-label="Permalink to &quot;Response Fields (201 Created)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>string</td><td><code>All compare items have been removed successfully</code>.</td></tr><tr><td><code>deletedCount</code></td><td>integer</td><td>How many rows were removed. <code>0</code> when the list was already empty.</td></tr></tbody></table><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><ul><li>Clears only the authenticated customer&#39;s rows. The comparison list is not channel-scoped, so one call empties it everywhere.</li><li>Repeating the call is safe; the second one answers <code>201</code> with <code>deletedCount: 0</code>.</li><li>The message reads the same whether rows were removed or not — read <code>deletedCount</code> to know what happened.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Clear comparison&quot; button</strong> — one call empties the table, and <code>deletedCount</code> tells the UI how many columns to drop without a re-fetch.</li><li><strong>Reset between comparison sessions</strong> — clearing is cheaper than deleting each row when the shopper starts a new set.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Confirm in the UI first</strong> — the call takes no ID and is irreversible.</li><li><strong>Read <code>deletedCount</code>, not <code>message</code></strong> — the message is identical on an empty list.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/compare/list.html">Get Compare Items</a> — the customer&#39;s comparison rows</li><li><a href="/api/rest-api/shop/compare/delete.html">Delete Compare Item</a> — remove one comparison row</li></ul>',19)]))}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
